import { useMemo, useState } from "react";
import { FileExplorer } from "./components/FileExplorer";
import { MarkdownEditor } from "./components/MarkdownEditor";
import { MarkdownViewer } from "./components/MarkdownViewer";
import { DocumentOutline } from "./components/DocumentOutline";
import { Settings } from "./components/Settings";
import { useDocumentState } from "./state/documentState";
import { useSession } from "./state/session";
import { isTauriRuntime } from "./lib/ipc";

export function App() {
  const session = useSession();
  const doc = useDocumentState();
  const [query, setQuery] = useState("");
  const view = useMemo(() => session.viewMode, [session.viewMode]);
  const tauri = isTauriRuntime();

  return (
    <div className={`app theme-${session.theme}`} role="application" aria-label="MD Studio">
      <header className="topbar">
        <div className="brand">
          <span className="brand-mark" aria-hidden>
            MD
          </span>
          <div>
            <strong>MD Studio</strong>
            <span className="brand-sub">
              {tauri ? "App local" : "Preview no browser"}
              {doc.relativePath ? ` · ${doc.relativePath}` : ""}
              {doc.dirty ? " · modificado" : ""}
            </span>
          </div>
        </div>
        <div className="topbar-actions">
          <button
            type="button"
            className="btn btn-primary btn-sm"
            onClick={() => void doc.save()}
            disabled={!doc.relativePath}
          >
            Salvar
          </button>
        </div>
      </header>

      <div className="workspace">
        <aside className="panel left" aria-label="Workspace">
          <FileExplorer
            workspace={doc.workspace}
            onOpenRelative={doc.openRelative}
            onOpenFolder={doc.openFolder}
            onOpenFile={doc.openFile}
            query={query}
            onQuery={setQuery}
            activePath={doc.relativePath}
          />
        </aside>

        <main className={`center mode-${view}`}>
          {view !== "preview" && (
            <MarkdownEditor
              value={doc.content}
              dirty={doc.dirty}
              onChange={doc.setContent}
              onSave={doc.save}
            />
          )}
          {view !== "source" && (
            <MarkdownViewer content={doc.content} relativePath={doc.relativePath} />
          )}
        </main>

        <aside className="panel right" aria-label="Metadados">
          <DocumentOutline content={doc.content} />
          <Settings session={session} />
          <section className="card" aria-label="Diagnósticos">
            <h2>Diagnósticos</h2>
            <ul className="diag-list">
              {doc.diagnostics.map((d, i) => (
                <li key={i}>{d}</li>
              ))}
            </ul>
          </section>
        </aside>
      </div>
    </div>
  );
}
